'use strict';
const {BASE,calculate,equilibria,variation,saw}=EOQ;
let state={...BASE},scenario='Base G1',graphCapacity='auto',sensitivityKey='D';
const money=x=>Number.isFinite(x)?new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:2}).format(x):'—';
const num=(x,d=2)=>Number.isFinite(x)?new Intl.NumberFormat('es-CO',{maximumFractionDigits:d}).format(x):'—';
const colors=['#087d68','#397bd5','#bd7528'];
const sections=[['resumen','Resumen y recomendación'],['datos','Datos y clasificación'],['eoq','EOQ sin restricciones'],['robustez','Lotes reales y robustez'],['capacidad','Capacidad'],['molde','Proveedor local y molde'],['comparacion','Comparación'],['graficas','Gráficas'],['sensibilidad','Sensibilidad'],['equilibrio','Puntos de equilibrio'],['gerencia','Preguntas de gerencia']];
document.querySelector('#nav').innerHTML=sections.map(([id,name],i)=>`<a href="#${id}">${String(i+1).padStart(2,'0')} · ${name}</a>`).join('');
const labels={D:['Demanda anual','unidades/año'],vi:['Precio importado','COP/unidad'],vl:['Precio local','COP/unidad'],sale:['Precio de venta','COP/unidad'],ads:['Publicidad','COP/año'],q20:['Lote completo 20 pies','unidades/pedido'],q40:['Lote completo 40 pies','unidades/pedido'],units:['Unidades por posición','unidades/posición'],positions:['Bodega actual','posiciones'],localCapacity:['Capacidad anual local','unidades/año'],rDirect:['Tasa total directa','% anual'],capital:['Capital','% anual'],insurance:['Seguro','% anual'],damage:['Deterioro y obsolescencia','% anual'],handling:['Manejo y otros','% anual'],f20:['Flete internacional 20 pies','COP/pedido'],c20:['Aduana y puerto 20 pies','COP/pedido'],t20:['Transporte nacional 20 pies','COP/pedido'],a20:['Administración 20 pies','COP/pedido'],f40:['Flete internacional 40 pies','COP/pedido'],c40:['Aduana y puerto 40 pies','COP/pedido'],t40:['Transporte nacional 40 pies','COP/pedido'],a40:['Administración 40 pies','COP/pedido'],tl:['Transporte local','COP/pedido'],il:['Recepción e inspección local','COP/pedido'],al:['Administración local','COP/pedido'],rentPositions:['Posiciones adicionales de alquiler','posiciones'],expandPositions:['Posiciones adicionales de ampliación','posiciones'],rent:['Alquiler completo','COP/año'],expand:['Ampliación equivalente','COP/año'],mold:['Molde equivalente','COP/año'],p:['Financiación del proveedor','% del molde']};
function fields(keys){return `<div class="grid">${keys.map(k=>`<label class="field">${labels[k][0]} <input aria-label="${labels[k][0]}" type="number" data-key="${k}" value="${Number.isFinite(state[k])?state[k]:''}" min="${['D','vi','vl','q20','q40','units'].includes(k)?'0.000001':'0'}" ${k==='p'?'max="100"':''} step="any" ${['capital','insurance','damage','handling'].includes(k)&&state.rMode==='direct'||k==='rDirect'&&state.rMode==='components'?'disabled':''}>${labels[k][1]}</label>`).join('')}</div>`;}
function table(headers,rows){return `<div class="scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function section(id,content,cls=''){return `<section id="${id}" class="${cls}"><h2>${sections.find(x=>x[0]===id)[1]}</h2>${content}</section>`;}
function winner(m){return m.winners.length?m.winners.map(x=>x.name).join(' / '):'Ninguna alternativa factible';}
function dataSection(){return section('datos',`<p>Campos editables con unidades. Los resultados de las siguientes etapas se calculan automáticamente. Cada demanda define un escenario constante nuevo.</p><h3>Demanda y adquisición</h3>${fields(['D','vi','vl'])}<h3>Ordenar · costos por pedido</h3>${fields(['f20','c20','t20','a20','f40','c40','t40','a40','tl','il','al'])}<h3>Almacenar · una sola tasa activa</h3><div class="controls"><select id="rMode" aria-label="Modo de tasa"><option value="components" ${state.rMode==='components'?'selected':''}>Suma de componentes</option><option value="direct" ${state.rMode==='direct'?'selected':''}>Tasa total directa</option></select></div>${fields(['capital','insurance','damage','handling','rDirect'])}<h3>Capacidad y restricciones físicas</h3>${fields(['q20','q40','units','positions','localCapacity','rentPositions','expandPositions','rent','expand'])}<h3>Molde · costo fijo anual de la fuente local</h3>${fields(['mold','p'])}<h3>Información que no determina Q</h3>${fields(['sale','ads'])}<p>El precio de venta y la publicidad no entran al EOQ ni al costo total comparativo. La adquisición entra al costo anual y v × r; los costos por pedido forman A; capital, seguro, deterioro y manejo forman r. Capacidad y lotes completos restringen la factibilidad. El molde es un costo fijo anual local: afecta la elección de fuente, pero no su EOQ.</p><p class="note">Sin faltantes, lead time, inventario de seguridad, descuentos ni fuentes combinadas. Pedidos/año puede ser no entero. No se vuelven a amortizar costos anuales equivalentes.</p>`);}
function render(){const m=calculate(state);document.querySelector('#scenario').textContent=scenario;document.querySelector('#errors').textContent=m.errors.length?'Complete o corrija los datos para obtener resultados: '+m.errors.join(' · '):'';if(m.errors.length){document.querySelector('#results').innerHTML=dataSection();bind();return;}const [a,b,l]=m.rows,eq=equilibria(state),first=m.ranked[0],next=m.ranked.find(x=>first&&x.total>first.total+.01);let html=section('resumen',`<span class="pill">${m.winners.length>1?'Empate económico':'Decisión del escenario activo'}</span><h2>${winner(m)}</h2><p>Elegimos el menor Costo Total Anual entre fuentes físicamente factibles.</p><div class="metrics"><div class="metric"><small>Costo Total Anual</small><strong>${first?money(first.total):'Sin solución'}</strong></div><div class="metric"><small>Bodega necesaria</small><strong>${first?m.winners.map(x=>x.chosen.name+' · '+num(x.positions,0)+' pos.').join(' / '):'—'}</strong></div><div class="metric"><small>Ahorro frente a la siguiente fuente factible</small><strong>${m.winners.length>1?'$0 · empate':next?money(next.total-first.total):'Sin otra fuente viable'}</strong></div></div>`,'hero');html+=dataSection();
html+=section('eoq',`<p>El EOQ equilibra ordenar y almacenar. Es una referencia sin restricciones; en importación usamos después el lote completo.</p><div class="formula">Q* = √(2 × A × D / (v × r)) · r activo = ${num(m.r*100)}%</div>${table(['Fuente','A / pedido','v / unidad','v × r / año','EOQ (unidades)','TRC mínimo'],m.rows.map(x=>[x.name,money(x.A),money(x.v),money(x.v*m.r),num(x.eoq,4),money(x.minTRC)]))}<p>No se redondea Q* para calcular costos. Solo las posiciones se redondean hacia arriba.</p>`);
html+=section('robustez',`<p>La robustez mide el costo de apartarnos del EOQ; la sensibilidad de la decisión se estudia por separado.</p>${table(['Contenedor','EOQ','Lote real','Δ unidades','|Δ| unidades','Δ %','|Δ| %','TRC real','TRC mínimo','Penalización COP','Penalización %'],[a,b].map(x=>[x.name,num(x.eoq),num(x.Q),num(x.delta),num(Math.abs(x.delta)),num(x.deltaPct)+'%',num(Math.abs(x.deltaPct))+'%',money(x.trc),money(x.minTRC),money(x.penalty),num(x.penaltyPct)+'%']))}<p>${[a,b].map(x=>`${x.name}: la desviación absoluta de cantidad es ${num(Math.abs(x.deltaPct))}% y aumenta el TRC ${num(x.penaltyPct)}%.`).join(' ')} La curva tiene un mínimo suave: una desviación considerable de Q puede tener una penalización menor en costo. Compare ambos porcentajes.</p>`);
html+=section('capacidad',`<div class="formula">Posiciones = ⌈Q / unidades por posición⌉ · inventario máximo = Q</div><p>Alquiler y ampliación son alternativas separadas. Se cobra su costo anual completo. El EOQ local no se reduce para hacerlo caber.</p>${table(['Política','Q máximo','Posiciones necesarias','Disponibles','Capacidad COP/año','Resultado'],m.rows.flatMap(x=>x.configs.map(c=>[x.name+' · '+c.name,num(x.Q),num(x.positions,0),num(c.positions,0),money(c.cost),c.feasible&&x.supply?'<span class="good">Factible</span>':`<span class="bad">${!x.supply?'Capacidad anual local insuficiente':'No cabe'}</span>`])))}<p>Estas filas desglosan las cinco posibilidades: actual/adicional para cada contenedor y EOQ local. La opción adicional más barata que cabe se selecciona automáticamente; la bodega actual tiene costo incremental cero.</p>`);
html+=section('molde',`<div class="formula">Molde empresa = costo anual equivalente × (1 − p)</div><div class="metrics"><div class="metric"><small>Financiación proveedor</small><strong>${num(state.p)}%</strong></div><div class="metric"><small>Molde a cargo de la empresa</small><strong>${money(l.mold)}</strong></div><div class="metric"><small>Capacidad anual local</small><strong>${num(state.localCapacity,0)} unidades</strong></div></div><p>Se interpreta que el molde corresponde únicamente al proveedor local, conforme a los controles G1. Su costo fijo se suma una vez al año. Estado local: ${l.feasible?'factible':!l.supply?'la capacidad anual no cubre toda la demanda':'el EOQ excede la capacidad de bodega'}.</p>`);
html+=section('comparacion',`<div class="formula">TRC = A × D/Q + v × r × Q/2<br>CTA = v × D + TRC + capacidad + molde local</div>${table(['Fuente','Pedidos/año','Inventario medio','Ciclo días','Adquisición','Ordenar','Almacenar','Capacidad','Molde','CTA','Clasificación'],m.rows.map(x=>[x.name,num(x.orders),num(x.average),num(x.cycle),money(x.acquisition),money(x.ordering),money(x.holding),x.chosen?money(x.chosen.cost):'Sin bodega viable',money(x.mold),money(x.total),x.feasible?'#'+(m.ranked.findIndex(y=>y.id===x.id)+1):'<span class="bad">Excluida: no factible</span>']))}<p>Los costos de una fuente no factible son informativos; si no hay bodega suficiente, su CTA mostrado omite un costo de capacidad que no puede cotizarse con estas opciones.</p><div id="costChart" class="chart"></div>`);
html+=section('graficas',`<h3>Inventario durante un año</h3><p>Posiciones equivalentes (Q/unidades por posición). Las reposiciones se dibujan en sus tiempos exactos; la restricción usa posiciones enteras redondeadas. Cada política muestra su capacidad seleccionada y cualquier exceso. En demandas extremas se muestran como máximo 10.000 ciclos; el costo sigue calculándose para toda la demanda.</p><div class="controls"><select id="graphCapacity" aria-label="Capacidad para gráfico"><option value="auto">Elección automática por política</option><option value="0">Bodega actual</option><option value="1">Alquiler</option><option value="2">Ampliación</option></select></div><div id="sawChart" class="chart"></div><h3>TRC frente a cantidad a pedir</h3><p>Ejes numéricos. Costos en millones de COP/año. Curvas continuas de ordenar, almacenar y TRC; marcadores EOQ y lote real. Mueva el cursor para consultar valores.</p>${m.rows.map(x=>`<h3>${x.name}</h3><div id="trc-${x.id}" class="chart"></div>`).join('')}`);
html+=section('sensibilidad',`<p>Cada punto modifica solo el parámetro seleccionado respecto al <strong>escenario activo: ${scenario}</strong>; los demás conservan sus valores. No se acumulan cambios entre puntos.</p><div class="controls"><select id="sensitivityKey" aria-label="Variable de sensibilidad">${['D','rDirect','vl','rent','expand','p'].map(k=>`<option value="${k}">${labels[k][0]}</option>`).join('')}</select></div><div id="sensitivityChart" class="chart"></div><div id="sensitivityTable"></div>`);
html+=section('equilibrio',`<p>Referencia: ${eq.importation?eq.importation.name+' · '+money(eq.importation.total):eq.error}</p><div class="columns"><div><h3>A · Precio local máximo competitivo</h3><div class="metric"><strong>${eq.price?money(eq.price)+'/unidad':'Sin umbral viable'}</strong></div><p>${eq.priceMessage||eq.error}</p>${eq.priceResult?`<p>EOQ ${num(eq.priceResult.eoq,4)} · ${eq.priceResult.positions} posiciones · ${eq.priceResult.chosen.name}. CTA local ${money(eq.priceResult.total)}. Diferencia con importación ${money(eq.priceResult.total-eq.importation.total)}.</p>`:''}</div><div><h3>B · Financiación mínima del molde</h3><div class="metric"><strong>${eq.finance!==null&&eq.finance!==undefined?num(eq.finance,4)+'%':'Sin umbral viable'}</strong></div><p>${eq.financeMessage||eq.error}</p>${eq.finance!==null&&eq.finance<=100?`<p>Con el precio activo, CTA local al umbral: ${money(calculate({...state,p:eq.finance}).rows[2].total)}. Si el umbral es 0%, el local ya puede competir.</p>`:''}</div></div><p>Al variar precio local se recalculan EOQ, posiciones y la opción de bodega factible más barata. El precio umbral debe cumplir también la capacidad anual. Los saltos de costo al cambiar de bodega se respetan.</p>`);
const base=calculate(BASE);html+=section('gerencia',`<p>Los botones restauran G1 y cambian únicamente el parámetro indicado. La tabla compara siempre contra G1, independientemente de las ediciones del escenario activo.</p><div class="controls">${['Base G1','1 · Local $99.000','2 · Flete 20 pies $10.000.000','3 · Molde financiado 50%'].map((text,i)=>`<button data-variation="${i}">${text}</button>`).join('')}</div>${table(['Caso','Recomendación','CTA ganador','Δ CTA ganador vs. base','Δ CTA 20 pies','Δ CTA local','¿Cambia fuente?'],[0,1,2,3].map(n=>{const v=calculate(variation(n));return [n?'Variación '+n:'Base G1',winner(v),money(v.ranked[0].total),money(v.ranked[0].total-base.ranked[0].total),money(v.rows[0].total-base.rows[0].total),money(v.rows[2].total-base.rows[2].total),winner(v)===winner(base)?'No':'Sí'];}))}`);
document.querySelector('#results').innerHTML=html;bind();charts(m);}
function bind(){document.querySelectorAll('[data-key]').forEach(input=>input.addEventListener('input',()=>{const key=input.dataset.key;state[key]=input.value.trim()===''?NaN:Number(input.value);scenario='Escenario personalizado';const focus={key,start:input.selectionStart};render();const target=document.querySelector(`[data-key="${focus.key}"]`);target?.focus();}));document.querySelector('#rMode')?.addEventListener('change',e=>{state.rMode=e.target.value;scenario='Escenario personalizado';render();});document.querySelectorAll('[data-variation]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.variation);state=variation(n);scenario=n?'Variación '+n+' desde G1':'Base G1';render();});const gc=document.querySelector('#graphCapacity');if(gc){gc.value=graphCapacity;gc.onchange=()=>{graphCapacity=gc.value;charts(calculate(state));};}const sk=document.querySelector('#sensitivityKey');if(sk){sk.value=sensitivityKey;sk.onchange=()=>{sensitivityKey=sk.value;sensitivity();};}}
document.querySelector('#reset').onclick=()=>{state={...BASE};scenario='Base G1';render();};document.querySelector('#export').onclick=()=>{const model=calculate(state);if(model.errors.length){alert('Corrija los datos antes de exportar.');return;}const blob=new Blob([JSON.stringify({scenario,parameters:state,model,equilibria:equilibria(state)},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='EOQ-G1-escenario.json';a.click();URL.revokeObjectURL(url);};
const tip=document.createElement('div');tip.className='tooltip';document.body.append(tip);
function attachTip(el,text){el.addEventListener('mousemove',e=>{tip.textContent=typeof text==='function'?text(e):text;tip.style.display='block';tip.style.left=Math.min(e.clientX+14,window.innerWidth-310)+'px';tip.style.top=Math.min(e.clientY+14,window.innerHeight-90)+'px';});el.addEventListener('mouseleave',()=>tip.style.display='none');}
function lineChart(id,series,{xmin=0,xmax,ymax,xlabel='Cantidad (unidades)',ylabel='Millones COP/año',marks=[]}={}){const el=document.getElementById(id);if(!el)return;const W=920,H=310,L=75,R=25,T=25,B=55;const sx=x=>L+(x-xmin)/(xmax-xmin)*(W-L-R),sy=y=>H-B-y/ymax*(H-T-B);let content='';for(let i=0;i<=5;i++){const y=ymax*i/5,x=xmin+(xmax-xmin)*i/5;content+=`<line x1="${L}" x2="${W-R}" y1="${sy(y)}" y2="${sy(y)}" stroke="#e4eae5"/><text x="${L-10}" y="${sy(y)+4}" text-anchor="end" font-size="11" fill="#58706b">${num(y,1)}</text><text x="${sx(x)}" y="${H-B+22}" text-anchor="middle" font-size="11" fill="#58706b">${num(x,0)}</text>`;}content+=`<text x="${L}" y="15" font-size="11">${ylabel}</text><text x="${W/2}" y="${H-8}" font-size="11" text-anchor="middle">${xlabel}</text>`;series.forEach((s,i)=>{content+=`<path data-series="${i}" d="${s.points.map(([x,y],j)=>`${j?'L':'M'}${sx(x).toFixed(4)},${sy(y).toFixed(4)}`).join(' ')}" fill="none" stroke="${s.color}" stroke-width="${s.dash?1.5:2}" ${s.dash?'stroke-dasharray="7 5"':''}/>`;});for(const mark of marks){content+=`<circle cx="${sx(mark.x)}" cy="${sy(mark.y)}" r="5" fill="${mark.color}"/><text x="${sx(mark.x)+7}" y="${sy(mark.y)-10}" font-size="11">${mark.name}</text>`;}content+=`<rect data-hover="1" x="${L}" y="${T}" width="${W-L-R}" height="${H-T-B}" fill="transparent"/>`;el.innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${ylabel} frente a ${xlabel}">${content}</svg><div class="legend">${series.map(s=>`<span><i class="dot" style="background:${s.color}"></i>${s.name}</span>`).join('')}</div>`;const hover=el.querySelector('[data-hover]');attachTip(hover,e=>{const rect=el.querySelector('svg').getBoundingClientRect();const px=(e.clientX-rect.left)/rect.width*W;const x=Math.max(xmin,Math.min(xmax,xmin+(px-L)/(W-L-R)*(xmax-xmin)));return series.map(s=>s.tooltip?s.tooltip(x):`${s.name}: ${num(s.points.reduce((best,p)=>Math.abs(p[0]-x)<Math.abs(best[0]-x)?p:best,s.points[0])[1])}`).join(' · ');});}
function charts(m){if(m.errors.length)return;const series=[];const names=['20 pies · EOQ referencia','20 pies · lote real','40 pies · EOQ referencia','40 pies · lote real','Local · EOQ'];const policies=[{row:m.rows[0],Q:m.rows[0].eoq,ref:true},{row:m.rows[0],Q:m.rows[0].Q},{row:m.rows[1],Q:m.rows[1].eoq,ref:true},{row:m.rows[1],Q:m.rows[1].Q},{row:m.rows[2],Q:m.rows[2].Q}];let ymax=0;const capacityLines=[];policies.forEach((p,i)=>{if(p.Q<=0)return;const configs=EOQ.capacity(state,p.Q);const chosen=graphCapacity==='auto'?configs.filter(c=>c.feasible).sort((a,b)=>a.cost-b.cost)[0]||configs.reduce((a,b)=>a.positions>b.positions?a:b):configs[Number(graphCapacity)];const exceeds=Math.ceil(p.Q/state.units)>chosen.positions;const color=colors[p.row.id==='20'?0:p.row.id==='40'?1:2];const T=365*p.Q/state.D;ymax=Math.max(ymax,p.Q/state.units,chosen.positions);series.push({name:names[i]+(exceeds?' · SUPERA CAPACIDAD':''),color,dash:p.ref,points:saw(p.Q,state.D,state.units),tooltip:day=>`${names[i]}: día ${num(day)} · ${num((p.Q-state.D/365*(day%T))/state.units)} pos. · ciclo ${num(T)} días`});if(!capacityLines.some(c=>c.positions===chosen.positions))capacityLines.push({...chosen,color});});capacityLines.forEach(c=>series.push({name:'Capacidad '+c.name+' · '+c.positions+' pos.',color:'#7c8580',dash:true,points:[[0,c.positions],[365,c.positions]],tooltip:()=>`Capacidad ${c.name}: ${c.positions} posiciones`}));lineChart('sawChart',series,{xmax:365,ymax:ymax*1.12,xlabel:'Día del año',ylabel:'Posiciones equivalentes'});
for(const row of m.rows){if(row.eoq<=0)continue;const xmin=Math.min(row.eoq,row.Q)*.35,xmax=Math.max(row.eoq,row.Q)*1.8;const points=Array.from({length:241},(_,i)=>xmin+(xmax-xmin)*i/240);const cost=q=>({ordering:row.A*state.D/q,holding:row.v*m.r*q/2});const s=[['ordering','Ordenar','#8db6a8'],['holding','Almacenar','#b9a36b'],['trc','TRC',colors[m.rows.indexOf(row)]]].map(([key,name,color])=>({name,color,points:points.map(q=>{const c=cost(q);return [q,(key==='trc'?c.ordering+c.holding:c[key])/1e6];}),tooltip:q=>{const c=cost(q);return `${name} · Q ${num(q)}: ${money(key==='trc'?c.ordering+c.holding:c[key])}`;}}));lineChart('trc-'+row.id,s,{xmin,xmax,ymax:Math.max(...s[2].points.map(x=>x[1]))*1.15,marks:[{name:'EOQ '+num(row.eoq),x:row.eoq,y:row.minTRC/1e6,color:colors[m.rows.indexOf(row)]},...(row.id==='local'?[]:[{name:'Lote '+num(row.Q),x:row.Q,y:row.trc/1e6,color:'#173b32'}])]});}costChart(m);sensitivity();}
function costChart(m){const el=document.getElementById('costChart');const W=920,H=250,L=100,scale=740/Math.max(...m.rows.map(x=>x.total));let svg='';const parts=[['acquisition','Adquisición','#cbdcd2'],['ordering','Ordenar','#087d68'],['holding','Almacenar','#397bd5'],['capacity','Capacidad','#bd7528'],['mold','Molde','#87619b']];m.rows.forEach((r,i)=>{const y=25+i*65;svg+=`<text x="10" y="${y+20}" font-size="13">${r.name}</text>`;let x=L;for(const [key,name,color] of parts){const value=key==='capacity'?(r.chosen?.cost||0):r[key];const width=value*scale;svg+=`<rect data-tip="${r.name} · ${name}: ${money(value)}" x="${x}" y="${y}" width="${width}" height="27" fill="${color}" opacity="${r.feasible?1:.35}"/>`;x+=width;}svg+=`<text x="${L}" y="${y+45}" font-size="12" fill="${r.feasible?'#18332f':'#af3a36'}">${money(r.total)} · ${r.feasible?'Factible':'NO FACTIBLE · fuera de clasificación'}</text>`;});el.innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Composición del costo total anual">${svg}</svg><div class="legend">${parts.map(([,n,c])=>`<span><i class="dot" style="background:${c}"></i>${n}</span>`).join('')}</div>`;el.querySelectorAll('[data-tip]').forEach(r=>attachTip(r,r.dataset.tip));}
function sensitivity(){const key=sensitivityKey;const base=key==='rDirect'?EOQ.rate(state)*100:state[key];const values=Array.from({length:21},(_,i)=>key==='p'?i*5:base===0?i*(key==='rent'||key==='expand'?1000000:1):base*(.5+i*.05));const models=values.map(value=>calculate({...state,[key]:value,...(key==='rDirect'?{rMode:'direct'}:{})}));let ymax=0;const series=colors.map((color,i)=>{const pts=[];models.forEach((m,j)=>{if(!m.errors.length&&m.rows[i].feasible){pts.push([values[j],m.rows[i].total/1e6]);ymax=Math.max(ymax,m.rows[i].total/1e6);}});return {name:['20 pies','40 pies','Local'][i]+' · tramos factibles',color,points:pts,tooltip:x=>{let j=values.reduce((a,v,k)=>Math.abs(v-x)<Math.abs(values[a]-x)?k:a,0);const row=models[j].rows?.[i];return `${['20 pies','40 pies','Local'][i]}: ${row?.feasible?money(row.total):'no factible'} a ${num(values[j])}`;}};}).filter(s=>s.points.length);if(series.length)lineChart('sensitivityChart',series,{xmin:values[0],xmax:values.at(-1),ymax:ymax*1.08,xlabel:labels[key][0]+' ('+labels[key][1]+')'});else document.getElementById('sensitivityChart').innerHTML='<p>Sin alternativas factibles en el rango.</p>';document.getElementById('sensitivityTable').innerHTML=table([labels[key][0],'20 pies CTA','40 pies CTA','Local CTA','Recomendación'],models.map((m,j)=>[num(values[j]),...((m.rows||[]).map(r=>r.feasible?money(r.total):'No factible')),m.errors.length?'Datos no válidos':winner(m)]));}
render();
